function checkInclusion(s1, s2) {
  const m = s1.length;
  const n = s2.length;
  if (m > n) return false;

  const targetSorted = s1.split('').sort().join('');
  for (let i = 0; i <= n - m; i++) {
    const windowStr = s2.slice(i, i + m).split('').sort().join('');
    if (windowStr === targetSorted) {
      return true;
    }
  }
  return false;
}

